#[test]
fn clear_does_not_retain_table_after_drop() -> Result<()> {
    let lua = Lua::new();
    let weak: mlua::Table = lua.load("setmetatable({}, {__mode='v'})").eval()?;
    let control = lua.create_table()?;
    weak.set(1, &control)?;
    drop(control);
    lua.gc_collect()?;
    lua.gc_collect()?;
    assert_eq!(weak.get::<Value>(1)?, Value::Nil);
    let table = lua.create_table()?;
    weak.set(1, &table)?;
    table.clear()?;
    drop(table);
    lua.gc_collect()?;
    lua.gc_collect()?;
    assert_eq!(weak.get::<Value>(1)?, Value::Nil);
    Ok(())
}

